<div class="form-grid"><x-field name="name" label="Library name" :value="$edit['name'] ?? ''" required /><label class="field"><span>Media type</span><select name="mediaType"><option value="book" @selected(($edit['mediaType'] ?? '') === 'book')>Audiobooks & ebooks</option><option value="podcast" @selected(($edit['mediaType'] ?? '') === 'podcast')>Podcasts & video</option></select></label><x-field name="provider" label="Metadata provider" :value="$edit['provider'] ?? ''" hint="For example google, audible, itunes, or a custom provider slug." /><x-field name="icon" label="Library icon" :value="$edit['icon'] ?? 'database'" /></div><x-field name="paths" label="Library folders (one absolute path per line)" type="textarea" rows="4" :value="collect($edit['folders'] ?? [])->pluck('fullPath')->join("\n")" required hint="Use paths inside the server container, such as /audiobooks or /podcasts." /><div class="form-grid"><x-field name="scanSchedule" label="Automatic scan schedule" :value="$edit['settings']['autoScanCronExpression'] ?? ''" hint="Optional cron expression." /><x-field name="markAsFinishedPercentComplete" label="Mark finished at (%)" type="number" :value="$edit['settings']['markAsFinishedPercentComplete'] ?? ''" min="0" max="100" /><x-field name="markAsFinishedTimeRemaining" label="Mark finished with seconds remaining" type="number" :value="$edit['settings']['markAsFinishedTimeRemaining'] ?? ''" min="0" /></div><label class="check"><input type="checkbox" name="disableWatcher" value="1" @checked($edit['settings']['disableWatcher'] ?? false)>Disable file watching for this library</label><label class="check"><input type="checkbox" name="disableAutoScan" value="1" @checked($edit['settings']['disableAutoScan'] ?? false)>Disable scheduled scans</label>
